$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'local-scoring-composition-v1.ps1')
. (Join-Path $PSScriptRoot 'local-tail-adapter-v1.ps1')
$frozen=Join-Path $PSScriptRoot 'score-mechanical-fresh-v3.ps1';$adapter=Join-Path $PSScriptRoot 'local-tail-adapter-v1.ps1'
$runRoot=Join-Path $PSScriptRoot ('public-composition-test-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory $runRoot
$utf8=[Text.UTF8Encoding]::new($false);$results=[Collections.Generic.List[object]]::new()
$tokens=$null;$errors=$null;$publicAst=[Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot 'test-local-tail-adapter-v1.ps1'),[ref]$tokens,[ref]$errors)
foreach($definition in $publicAst.EndBlock.Statements|Where-Object {$_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -in @('WriteJson','ReadJson','WriteRows','Digest','Assert','Reseal','Seed')}){. ([scriptblock]::Create($definition.Extent.Text))}
function Case($name,[scriptblock]$body){& $body;$results.Add(@{name=$name;status='pass'});Write-Output ('PASS '+$name)}
function Corpus([switch]$Ordinary){
 $script:testRoot=Join-Path $runRoot ([guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory $script:testRoot
 Seed -Ordinary:$Ordinary
 $script:episodes=@();$script:goldens=@()
 foreach($p in $script:plan|Where-Object masked_arm_id -CEQ 'public-arm-a'){
  $steps=@();foreach($s in $p.steps){$steps+=@{id=$s.id;evaluate=$s.evaluate;event=@{type=$(if($s.evaluate){'owner_message'}else{'manual_resource_change'});provenance='owner_report'}}}
  $script:episodes+=@{id=$p.episode_id;family=$p.family;steps=$steps}
  $script:goldens+=@{id=$p.episode_id;boundary='PUBLIC operational parser fixture';expected=@{tasks=@{A='active'};task_goal=@{A='public-goal'};preserve_goal=@('A');object_body=@{draft='public-body'};agent_commit_count=@{draft=0};clarification=@{'public-turn-1'=$false;'public-turn-2'=$false};next_action=@{'public-turn-1'='answer';'public-turn-2'='answer'};proposed_profile_update=@{'public-turn-1'='none';'public-turn-2'='none'};communication='PUBLIC unassessed';profile_mutation='none';no_control_events=$true}}
 }
 $task=@{task_id='public-task';status='active';goal='public-goal';revision=1;constraints=@();working=@{plan=@('public-plan')}}
 $object=@{key='draft';body='public-body';sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes('public-body'))).ToLowerInvariant();version=1;prepared_body=$null;commit_count=0}
 $index=ReadJson 'index.json';$index.episodes[0].aliases_path=$armDir+'/aliases.json';WriteJson 'index.json' $index
 WriteJson ($armDir+'/aliases.json') @{tasks=@{A=@{task_id='public-task'}}}
 foreach($s in $index.episodes[0].steps){foreach($path in @($s.before_snapshot_path,$s.after_snapshot_path)){if($path){WriteJson $path @{tasks=@($task);objects=@($object);profiles=@();deletion_manifest_sha256=(Digest ($armDir+'/deletions.log'));deletion_watermark=0}}}}
 $answer=@{answer='PUBLIC operational answer';needs_clarification=$false;next_action=@{kind='answer'};proposed_profile_update=@{kind='none'};completion_claim='not_complete'}
 WriteRows 'run_final_results' @(@{run_id='public-run';result_id='public-result';verdict='unverified';content=(ConvertTo-Json -InputObject $answer -Compress -Depth 20)},@{run_id='public-auto';result_id='public-auto-result';verdict='unverified';content=(ConvertTo-Json -InputObject $answer -Compress -Depth 20)})
 BindPublicFiles
}
function BindPublicFiles {
 $stimulusLines=@($script:episodes|ForEach-Object {ConvertTo-Json -InputObject $_ -Compress -Depth 100}) -join "`n";$goldenLines=@($script:goldens|ForEach-Object {ConvertTo-Json -InputObject $_ -Compress -Depth 100}) -join "`n"
 [IO.File]::WriteAllText((Join-Path $testRoot 'public-stimuli.jsonl'),$stimulusLines,$utf8);[IO.File]::WriteAllText((Join-Path $testRoot 'public-goldens.jsonl'),$goldenLines,$utf8)
 $script:pin.stimuli_sha256=Digest 'public-stimuli.jsonl';$script:pin.expectations_sha256=Digest 'public-goldens.jsonl'
 $m=ReadJson 'manifest.json';$m.stimuli_sha256=$pin.stimuli_sha256;$m.expectations_sha256=$pin.expectations_sha256;WriteJson 'manifest.json' $m
 $i=ReadJson 'index.json';$i.stimuli_sha256=$pin.stimuli_sha256;WriteJson 'index.json' $i;Reseal
}
function NewResult {Invoke-Issue76LocalScoringFiles -ReportRoot $testRoot -StimuliPath (Join-Path $testRoot 'public-stimuli.jsonl') -GoldensPath (Join-Path $testRoot 'public-goldens.jsonl') -Pin $pin -FrozenScorerPath $frozen -AdapterPath $adapter}
function OldResult {
 $copyDir=Join-Path $testRoot 'public-original-engine';$null=New-Item -ItemType Directory $copyDir
 [IO.File]::Copy($frozen,(Join-Path $copyDir 'score-mechanical-fresh-v3.ps1'))
 WriteJson 'public-original-engine/public-commitment-fresh-v3.json' @{stimuli_path='../public-stimuli.jsonl';expectations_path='../public-goldens.jsonl';stimuli_sha256=$pin.stimuli_sha256;expectations_sha256=$pin.expectations_sha256}
 $index=ReadJson 'index.json';$index.version='behavior76-checker-index-v1';WriteJson 'public-old-index.json' $index
 $out=Join-Path $testRoot 'public-original-output'
 $null=& (Join-Path $copyDir 'score-mechanical-fresh-v3.ps1') -IndexPath (Join-Path $testRoot 'public-old-index.json') -OutputRoot $out
 return @(ConvertFrom-Json ([IO.File]::ReadAllText((Join-Path $out 'mechanical-checks.json'))) -AsHashtable -Depth 100)
}
Case 'ordinary_checks_identical_to_byte_exact_old_scorer' {Corpus -Ordinary;$old=OldResult;$new=NewResult;$a=@($old|Sort-Object {$_['check']});$b=@($new.mechanical_checks|Where-Object {$_.check -notlike 'original-owner-opportunity:*'}|Sort-Object {$_['check']});if((Get-Issue76Canonical $a) -cne (Get-Issue76Canonical $b)){WriteJson 'public-debug-old.json' $a;WriteJson 'public-debug-new.json' $b;Write-Output ('PUBLIC_DEBUG '+$testRoot)};Assert ((Get-Issue76Canonical $a) -ceq (Get-Issue76Canonical $b)) 'Executed criterion results differ from original';Assert (@($b|Where-Object {$_.verdict -ceq 'fail' -and $_.kind -cne 'matrix'}).Count -eq 0) 'Positive ordinary fixture failed';Assert ($new.owner_rows.Count -eq 96) 'Original denominator lost'}
Case 'ordinary_negative_clarification_same_old_failure' {Corpus -Ordinary;$goldens[0].expected.clarification['public-turn-1']=$true;BindPublicFiles;$old=OldResult;$new=NewResult;$a=@($old|Where-Object check -CEQ 'clarification:public-turn-1');$b=@($new.mechanical_checks|Where-Object check -CEQ 'clarification:public-turn-1');Assert ($a.Count -eq 1 -and $b.Count -eq 1 -and $a[0].verdict -ceq 'fail' -and (Get-Issue76Canonical $a) -ceq (Get-Issue76Canonical $b)) 'Original negative criterion changed'}
Case 'tail_expected_denial_unavailable_before_snapshot_or_denial_logic' {Corpus;$goldens[0].expected.expected_admission_denial=@{'public-turn-2'=$true};$goldens[0].expected.tasks.A='completed';BindPublicFiles;$r=NewResult;$tail=@($r.owner_rows|Where-Object disposition -CEQ 'not_executed_after_fixture_local_unknown');Assert ($tail.Count -eq 1 -and $tail[0].verdict -ceq 'unavailable') 'Tail promoted';Assert (@($r.mechanical_checks|Where-Object check -CEQ 'expected-admission-denial:public-turn-2').Count -eq 0) 'Unexecuted denial was evaluated';Assert (@($r.mechanical_checks|Where-Object check -CEQ 'task-status:A').Count -eq 0) 'Earlier snapshot reused as original final';Assert ($r.availability.snapshot_reads.Count -eq 2 -and $r.owner_rows.Count -eq 96) 'Tail opened snapshots or denominator changed';Assert (@($r.mechanical_checks|Where-Object check -CEQ 'clarification:public-turn-1').Count -eq 1) 'Actual stopping turn skipped'}
Case 'owner_and_automatic_critical_failures_survive_local_tail' {Corpus;$answer=@{answer='PUBLIC';needs_clarification=$false;next_action=@{kind='answer'};proposed_profile_update=@{kind='none'};completion_claim='owner_verified'};WriteRows 'run_final_results' @(@{run_id='public-run';result_id='public-result';verdict='unverified';content=(ConvertTo-Json -InputObject $answer -Compress -Depth 20)},@{run_id='public-auto';result_id='public-auto-result';verdict='verified';content='{}'});Reseal;$r=NewResult;Assert (@($r.mechanical_checks|Where-Object {$_.check -ceq 'not-owner-verified:public-turn-1' -and $_.verdict -ceq 'fail'}).Count -eq 1) 'Owner violation erased';Assert (@($r.mechanical_checks|Where-Object {$_.check -ceq 'unverified-final:public-auto-result' -and $_.verdict -ceq 'fail'}).Count -eq 1) 'Automatic violation erased';Assert ($r.critical_unknown_refs.Count -eq 1 -and $r.critical_unknown_refs[0].success -ceq $false) 'UNKNOWN success synthesized'}
Case 'actual_unknown_commit_remains_original_confirmed_commit_failure' {Corpus;WriteRows 'behavior76_object_events' @(@{n=1;kind='commit';action_id='public-effect';before_state=@{version=1;sha256='PUBLIC';task_id='public-task'};after_state=@{body='PUBLIC'}});Reseal;$r=NewResult;Assert (@($r.mechanical_checks|Where-Object {$_.check -ceq 'confirmed-commit:1' -and $_.verdict -ceq 'fail'}).Count -eq 1) 'Observed uncertain commit became unavailable/pass'}
Case 'foreign_stop_binding_is_integrity_failure_before_scoring' {Corpus;WriteRows 'behavior76_recipient_diagnostics' @(@{action_id='public-effect';run_id='foreign';tool_call_id='public-tool';category='lost_ack'});Reseal;$caught=$false;try{$null=NewResult}catch{$caught=$true};Assert $caught 'Invalid stop reached scoring'}
Case 'executed_empty_snapshot_not_inferred_tail' {Corpus -Ordinary;$i=ReadJson 'index.json';$i.episodes[0].steps[0].before_snapshot_path='';WriteJson 'index.json' $i;Reseal;$caught=$false;try{$null=NewResult}catch{$caught=$true};Assert $caught 'Missing actual snapshot silently accepted'}
Case 'golden_hash_tamper_rejected' {Corpus;[IO.File]::AppendAllText((Join-Path $testRoot 'public-goldens.jsonl'),' ',$utf8);$caught=$false;try{$null=NewResult}catch{$caught=$true};Assert $caught 'Unpinned golden bytes accepted'}
Case 'missing_authoritative_owner_final_remains_unavailable_96_semantic_rows' {Corpus -Ordinary;WriteRows 'run_final_results' @(@{run_id='public-auto';result_id='public-auto-result';verdict='unverified';content='{}'});Reseal;$r=NewResult;Assert ($r.masked_semantic_template.Count -eq 96 -and @($r.masked_semantic_template|Where-Object {$_.episode_id -ceq 'public-episode-1' -and $_.masked_arm_id -ceq 'public-arm-a' -and $_.verdict -ceq 'unavailable'}).Count -eq 2) 'Missing owner final promoted or lost';Assert (@($r.mechanical_checks|Where-Object {$_.check -like 'one-authoritative-final:*' -and $_.verdict -ceq 'unavailable'}).Count -eq 2) 'Frozen missing-final rule bypassed'}
Case 'actual_expected_denial_distinct_from_unexecuted_tail' {Corpus -Ordinary;$goldens[0].expected.expected_admission_denial=@{'public-turn-2'=$true};$i=ReadJson 'index.json';$path=$i.episodes[0].steps[2].outcome_path;$o=ReadJson $path;$o.state='admission_denied';$o.owner_input_id='';$o.owner_run_id='';$o.run_ids=@();$o.automatic_run_ids=@();$o.native_entry_ids=@();WriteJson $path $o;BindPublicFiles;$r=NewResult;Assert (@($r.mechanical_checks|Where-Object {$_.check -ceq 'expected-admission-denial:public-turn-2' -and $_.verdict -ceq 'pass'}).Count -eq 1) 'Actual denial rule changed';Assert (@($r.masked_semantic_template|Where-Object {$_.step_id -ceq 'public-turn-2' -and $_.verdict -ceq 'not_applicable_actual_expected_denial'}).Count -eq 1) 'Actual denial confused with skipped tail';Assert ($r.masked_semantic_template.Count -eq 96) 'Semantic denominator lost'}
Case 'skipped_read_commit_profile_and_Stop_requirements_unavailable' {Corpus;$goldens[0].expected.require_post_event_read=@{step='public-turn-2';resource='draft';body='unobserved-PUBLIC'};$goldens[0].expected.no_commit_before=@{step='public-turn-2';resources=@('draft')};$goldens[0].expected.post_event_profile_summary='unobserved-PUBLIC';$goldens[0].expected.native_entries_after_stop=0;BindPublicFiles;$r=NewResult;foreach($id in @('post-event-independent-read','no-premature-commit:draft','corrected-profile-current','no-native-after-stop')){Assert (@($r.mechanical_checks|Where-Object {$_.check -ceq $id -and $_.verdict -ceq 'unavailable'}).Count -eq 1) ('Skipped criterion falsely evaluated: '+$id)};Assert ($r.masked_semantic_template.Count -eq 96 -and $r.critical_unknown_is_success -ceq $false) 'Original missingness/UNKNOWN rejection lost'}
Case 'original_function_and_criterion_extents_pinned' {$k=Get-Issue76FrozenKernel $frozen;Assert ($k.source_sha256 -ceq 'e481f9c062a3bc4500b9f0b94da8819fbf287bec075490583cad17d54198721d' -and @($k.witnesses|Where-Object kind -CEQ 'function').Count -ge 10 -and @($k.witnesses|Where-Object kind -CEQ 'statement').Count -eq 27) 'Frozen kernel extraction identity changed'}
$receipt=@{version='issue76-public-scoring-composition-selftest-v1';passed=$results.Count;failed=0;criteria_source_sha256='e481f9c062a3bc4500b9f0b94da8819fbf287bec075490583cad17d54198721d';criteria_changed=$false;thresholds_changed=$false;provider_calls=0;mapping_read=$false;hidden_controls_read=$false;tests=$results.ToArray();public_test_root=$runRoot}
[IO.File]::WriteAllText((Join-Path $runRoot 'selftest-receipt.json'),(ConvertTo-Json -InputObject $receipt -Depth 30)+"`n",$utf8)
Write-Output ('SELFTEST_PASS '+$results.Count+' '+$runRoot)
